def O(n):
    if n < 0: return None # Should not happen for positive integers
    # (i) Remove the last digit: n // 10
    # (ii) Add 3 times the removed digit: 3 * (n % 10)
    return (n // 10) + 3 * (n % 10)

def find_cycles(max_n=500, max_iter=100):
    cycle_data = {}

    for start_n in range(1, max_n + 1):
        sequence = []
        seen = {} # value -> iteration count
        current = start_n

        for i in range(max_iter):
            if current in seen:
                start_cycle_index = seen[current]
                cycle_length = i - start_cycle_index
                cycle = tuple(sequence[start_cycle_index:])

                if cycle_length > 0:
                    if cycle not in cycle_data:
                        cycle_data[cycle] = {'length': cycle_length, 'elements': list(cycle)}
                    else:
                        # Handle case where same cycle is reached from different entry points
                        pass 

                # Store the state that led to the cycle
                break

            seen[current] = len(sequence)
            sequence.append(current)
            current = O(current)

        # If we hit max_iter without a cycle, record the sequence segment if it's long
        if current != -1:
            # This path means it might be growing or taking too long, but since we expect convergence, we focus on detected cycles.
            pass

    # Extract unique cycle information
    cycles = []
    for cycle in cycle_data:
        cycles.append(cycle_data[cycle])

    return cycles

# Run simulation
cycles = find_cycles(max_n=500)
print(f"Found {len(cycles)} unique cycles.")
for i, cycle in enumerate(cycles):
    print(f"Cycle {i+1}: Length={cycle['length']}, Elements={cycle['elements']}")

